<template><view class="page-content" :class="{'with-action':['productEdit','entityEdit','accountEdit'].includes(screen)}">
 <template v-if="screen==='dashboard'">
  <view class="row between mb16"><view class="row"><view class="avatar"><FIcon name="user"/></view><view><text class="strong">管理员</text><text class="small muted block mt4">平台经营管理</text></view></view><text class="filter-pill">{{today()}}</text></view><view class="money-panel"><text class="small">今日销售额</text><text class="huge-number block mt12">¥{{money(sum(todayOrders))}}</text><text class="small block mt8 subtle-white">订单金额汇总</text></view><view class="three-columns card summary-row"><view v-for="m in metrics" :key="m.label" @tap="go('adminOrders',{filter:m.filter})"><text class="small muted">{{m.label}}</text><text class="number block mt8">{{m.value}}<text class="unit"> 单</text></text></view></view><view class="card"><view class="row between"><text class="h2">近7日订单</text><text class="small muted">单位：单</text></view><view class="bar-chart"><view v-for="d in chart" :key="d.date" class="chart-column"><text class="small">{{d.count}}</text><view class="bar" :style="{height:Math.max(4,d.count/chartMax*82)+'px'}"/><text class="tiny muted">{{d.date.slice(5)}}</text></view></view></view><view class="management-shortcuts"><button v-for="m in shortcuts" :key="m.screen" @tap="go(m.screen)"><view class="icon-tile"><FIcon :name="m.icon"/></view><view><text class="strong">{{m.label}}</text><text class="tiny muted block mt4">{{m.note}}</text></view></button></view><view class="section-head"><text class="h2">最新订单</text><text class="small muted" @tap="go('adminOrders')">查看全部 ›</text></view><OrderCard v-for="o in state.orders.slice(0,3)" :key="o.id" :order="o"/>
 </template>
 <template v-else-if="screen==='products'">
  <view class="row between mb16"><text class="small muted">共{{state.products.length}}种食材</text><button class="btn small-btn" @tap="go('productEdit')">＋ 新增</button></view><view class="search"><FIcon name="search" :size="18"/><input v-model="search" placeholder="搜索食材名称" aria-label="搜索食材名称"/></view><view class="tabs pills"><button v-for="c in categories" :key="c" :class="{active:category===c}" @tap="category=c">{{c}}</button></view><view class="tabs"><button v-for="v in activeFilters" :key="v.value" :class="{active:activeFilter===v.value}" @tap="activeFilter=v.value">{{v.label}}</button></view><view v-for="p in filteredProducts" :key="p.id" class="card row"><FoodPhoto :image="p.image" class="admin-product-photo" variant="admin-product-photo"/><view class="grow"><view class="row between"><text class="strong">{{p.name}}</text><text class="badge" :class="p.active?'completed':'cancelled'">{{p.active?'已上架':'已下架'}}</text></view><text class="small muted block mt8">{{p.spec}} · {{p.unit}}</text><text class="price strong block mt8">¥{{money(p.price)}}<text class="unit"> / {{p.unit}}</text></text><view class="row actions mt12"><button class="btn small-btn secondary" @tap="go('productEdit',{id:p.id})">编辑</button><button class="btn small-btn secondary" :disabled="busy" @tap="toggleProduct(p)">{{p.active?'下架':'上架'}}</button></view></view></view><view v-if="!filteredProducts.length" class="empty">暂无符合条件的食材</view>
 </template>
 <template v-else-if="screen==='productEdit'">
  <view class="upload-preview" @tap="chooseImage"><FoodPhoto :image="productForm.image" class="product-hero" variant="product-hero"/><view class="upload-label"><FIcon name="camera" :size="18"/>更换图片</view></view><view class="image-options"><button v-for="n in 6" :key="n" :class="{selected:String(productForm.image)===String(n-1)}" @tap="productForm.image=String(n-1)"><FoodPhoto :image="String(n-1)"/></button></view><view class="card"><text class="h2">基本信息</text><label class="field horizontal"><text>食材名称</text><input v-model="productForm.name" placeholder="请输入食材名称" aria-label="食材名称"/></label><view class="field horizontal"><text>所属分类</text><FSelect v-model="productForm.category" :options="categoryOptions"/></view><label class="field horizontal"><text>规格</text><input v-model="productForm.spec" aria-label="规格"/></label><label class="field horizontal"><text>计价单位</text><input v-model="productForm.unit" aria-label="计价单位"/></label></view><view class="card"><text class="h2">销售设置</text><label class="field horizontal"><text>销售价格</text><input v-model="productForm.price" type="digit" aria-label="销售价格"/></label><label class="field horizontal"><text>起订数量</text><input v-model="productForm.minimum" type="digit" aria-label="起订数量"/></label><view class="field horizontal"><text>商品状态</text><switch :checked="!!productForm.active" color="#154D3D" @change="productForm.active=$event.detail.value?1:0"/><text>{{productForm.active?'已上架':'已下架'}}</text></view><label class="field"><text>商品描述</text><textarea v-model="productForm.description" maxlength="500" aria-label="商品描述"/></label><text class="tiny muted">新价格仅对后续新订单生效</text></view><view class="action-bar"><button class="btn secondary grow" @tap="back">取消</button><button class="btn grow" :disabled="busy" @tap="saveProduct">保存修改</button></view>
 </template>
 <template v-else-if="screen==='stores'||screen==='suppliers'">
  <view class="row between mb16"><text class="small muted">合作{{screen==='stores'?'门店':'供应商'}} {{entities.length}}{{screen==='stores'?'家':'家'}}</text><button class="btn small-btn" @tap="go('entityEdit',{filter:screen})">＋ 新增{{screen==='stores'?'门店':''}}</button></view><view class="search"><FIcon name="search" :size="18"/><input v-model="search" :placeholder="screen==='stores'?'搜索门店名称、联系人':'供应商名称、联系人'"/></view><view class="tabs"><button v-for="s in entityStates" :key="s.value" :class="{active:activeFilter===s.value}" @tap="activeFilter=s.value">{{s.label}}</button></view><view v-for="e in filteredEntities" :key="e.id" class="card entity-card"><view class="row"><view class="avatar large"><FIcon :name="screen==='stores'?'store':'leaf'" :size="27"/></view><view class="grow"><view class="row between"><text class="h2">{{e.name}}</text><text class="badge" :class="e.active?'completed':'cancelled'">{{e.active?(screen==='stores'?'启用中':'合作中'):'已停用'}}</text></view><text class="small muted block mt12">联系人　{{e.contact}}　{{e.phone}}</text><template v-if="screen==='stores'"><text class="small muted block mt8">地址　{{e.address}}</text><text class="small block mt8">负责供应商　<text class="green strong">{{e.supplierName||'未绑定'}}</text></text></template><template v-else><view class="row wrap mt12"><text class="muted small">负责门店</text><text v-for="s in state.stores.filter(s=>s.supplier_id===e.id)" :key="s.id" class="badge completed">{{s.name}}</text><text v-if="!state.stores.some(s=>s.supplier_id===e.id)" class="muted small">暂无绑定门店</text></view></template><view class="row actions mt16"><button class="btn secondary small-btn" @tap="go('adminOrders',{filter:(screen==='stores'?'store:':'supplier:')+e.id})">查看订单</button><button class="btn secondary small-btn" @tap="go('entityEdit',{filter:screen,id:e.id})">编辑资料</button></view></view></view></view><view v-if="!filteredEntities.length" class="empty">暂无符合条件的记录</view>
 </template>
 <template v-else-if="screen==='entityEdit'">
  <view class="card"><text class="h2">{{filter==='stores'?'门店信息':'供应商信息'}}</text><label class="field"><text>名称</text><input v-model="entityForm.name" aria-label="名称"/></label><label class="field"><text>联系人</text><input v-model="entityForm.contact" aria-label="联系人"/></label><label class="field"><text>联系电话</text><input v-model="entityForm.phone" aria-label="联系电话"/></label><label v-if="filter==='stores'" class="field"><text>收货地址</text><textarea v-model="entityForm.address" aria-label="收货地址"/></label><view class="field horizontal"><text>启用状态</text><switch :checked="!!entityForm.active" color="#154D3D" @change="entityForm.active=$event.detail.value?1:0"/><text>{{entityForm.active?'启用中':'已停用'}}</text></view><text class="small muted block mt12">{{filter==='stores'?'新增门店后，请在配送关系中绑定供应商，并在账号管理中创建采购账号。':'新增供应商后，可绑定负责门店并创建供应商账号。'}}</text></view><view class="action-bar"><button class="btn secondary grow" @tap="back">取消</button><button class="btn grow" :disabled="busy" @tap="saveEntity">保存资料</button></view>
 </template>
 <template v-else-if="screen==='bindings'">
  <view class="notice row"><FIcon name="truck" :size="30"/><view><text class="strong">按门店自动分单</text><text class="small muted block mt8">门店下单后，订单自动分配给指定供应商</text></view></view><view class="search mt16"><FIcon name="search" :size="18"/><input v-model="search" placeholder="搜索门店名称"/></view><text class="small muted block mb16">{{state.stores.length}}家门店 · {{state.stores.filter(s=>s.supplier_id).length}}家已绑定</text><view v-for="s in state.stores.filter(s=>s.name.includes(search))" :key="s.id" class="card"><view class="row between"><view class="row"><view class="avatar"><FIcon name="store"/></view><view><text class="strong">{{s.name}}</text><text class="small muted block mt4">{{s.supplier_id?'已绑定':'未绑定'}}</text></view></view><FIcon name="arrow"/><text class="strong green">{{s.supplierName||'选择供应商'}}</text></view><view class="row mt16"><FSelect class="grow" :model-value="bindings[s.id]||s.supplier_id||0" :options="supplierOptions" @update:model-value="bindings[s.id]=$event"/><button class="btn small-btn" :disabled="busy||!(bindings[s.id]||s.supplier_id)" @tap="saveBinding(s)">确认绑定</button></view></view><view class="notice warning small">供应商仅可查看所负责订单。更换绑定只影响后续新订单，历史订单继续由原供应商履约。</view>
 </template>
 <template v-else-if="screen==='adminOrders'">
  <view class="search"><FIcon name="search" :size="18"/><input v-model="search" placeholder="搜索订单、门店、食材" aria-label="搜索平台订单"/></view><view class="row filters-row"><picker mode="date" :value="selectedDate" @change="selectedDate=$event.detail.value"><view class="filter-pill">{{selectedDate||'日期'}}⌄</view></picker><FSelect v-model="storeFilter" :options="storeOptions"/><FSelect v-model="supplierFilter" :options="supplierOptions"/></view><button v-if="selectedDate" class="text-button muted small" @tap="selectedDate=''">清除日期筛选</button><view class="tabs scroll-tabs"><button v-for="t in orderTabs" :key="t.value" :class="{active:status===t.value}" @tap="status=t.value">{{t.label}}</button></view><view class="three-columns summary-row"><view><text class="small muted">今日订单</text><text class="number block mt8">{{todayOrders.length}}<text class="unit">单</text></text></view><view><text class="small muted">待处理</text><text class="number block mt8">{{state.orders.filter(o=>o.status==='pending').length}}<text class="unit">单</text></text></view><view><text class="small muted">异常</text><text class="price number block mt8">{{state.orders.filter(o=>o.status==='issue').length}}<text class="unit">单</text></text></view></view><OrderCard v-for="o in filteredOrders" :key="o.id" :order="o"/><view v-if="!filteredOrders.length" class="empty">暂无相关订单</view><button class="btn secondary full mt16" :disabled="busy" @tap="exportOrders">导出订单</button>
 </template>
 <template v-else-if="screen==='reports'">
  <view class="row between mb16"><picker mode="date" :value="dateFrom" @change="dateFrom=$event.detail.value"><text class="filter-pill">{{dateFrom}} 起</text></picker><picker mode="date" :value="dateTo" @change="dateTo=$event.detail.value"><text class="filter-pill">至 {{dateTo}}</text></picker><button class="text-button green small" @tap="exportReports">导出</button></view><view class="money-panel"><text class="small">订单金额（按订单汇总）</text><text class="huge-number block mt8">¥{{money(sum(periodOrders))}}</text><view class="two-columns mt16"><view><text class="small">已结算</text><text class="strong block mt8">¥{{money(sumPaid(periodOrders))}}</text></view><view><text class="small">待结算（已收货）</text><text class="strong warm block mt8">¥{{money(due(periodOrders))}}</text></view></view></view><view class="tabs"><button :class="{active:group==='store'}" @tap="group='store'">按门店</button><button :class="{active:group==='supplier'}" @tap="group='supplier'">按供应商</button></view><view v-for="r in reportRows" :key="r.id" class="card"><view class="row between"><text class="h2">{{r.name}}</text><text class="small">本期采购 ¥{{money(sum(r.orders))}}</text></view><view class="two-columns mt16"><view><text class="small muted">已结算</text><text class="strong green block mt8">¥{{money(sumPaid(r.orders))}}</text></view><view><text class="small muted">待结算</text><text class="strong price block mt8">¥{{money(due(r.orders))}}</text></view></view><view class="row actions mt16"><button class="text-button small muted" @tap="go('adminOrders',{filter:group+':'+r.id})">查看明细 ›</button><button v-if="group==='store'&&due(r.orders)>0" class="btn secondary small-btn" @tap="go('settlements',{id:r.id})">登记结算</button></view></view><text class="small muted center block mt16">按供应商查看的是门店销售订单汇总</text>
 </template>
 <template v-else-if="screen==='settlements'">
  <FSelect v-model="storeFilter" :options="storeOptions"/><view class="light-panel mt16"><text class="small">已登记线下结算</text><text class="huge-number block mt8">¥{{money(filteredSettlements.reduce((s,r)=>s+Number(r.amount),0))}}</text></view><view class="section-head"><text class="h2">最近结算记录</text><button class="text-button small green" @tap="exportSettlements">导出</button></view><view v-for="s in filteredSettlements" :key="s.id" class="card"><view class="row between"><text class="strong">{{s.storeName}}</text><text class="badge completed">已登记</text></view><text class="number block mt8">¥{{money(s.amount)}}</text><text class="small muted block mt8">{{s.settlement_date}} · {{s.note}}</text></view><view v-if="!filteredSettlements.length" class="empty compact">暂无结算记录</view><view class="card"><text class="h2">新增结算记录</text><view class="field horizontal"><text>门店</text><FSelect v-model="settlementForm.storeId" :options="storeOptions"/></view><text class="small muted">当前可结算：¥{{money(settlementAvailable)}}</text><label class="field horizontal"><text>结算金额</text><input v-model="settlementForm.amount" type="digit" placeholder="请输入金额" aria-label="结算金额"/></label><view class="field horizontal"><text>结算日期</text><picker mode="date" :value="settlementForm.date" :end="today()" @change="settlementForm.date=$event.detail.value"><view class="select-field">{{settlementForm.date}}<FIcon name="calendar" :size="16"/></view></picker></view><label class="field"><text>备注</text><textarea v-model="settlementForm.note" placeholder="填写线下收款说明" maxlength="500" aria-label="结算备注"/></label><text class="small muted block mt16">仅登记已完成的线下收款，金额会分配到已收货的未结清订单。</text><button class="btn full mt16" :disabled="busy" @tap="saveSettlement">保存结算记录</button></view>
 </template>
 <template v-else-if="screen==='accounts'">
  <view class="tabs pills"><button v-for="r in roleOptions" :key="r.value" :class="{active:accountRole===r.value}" @tap="accountRole=r.value">{{r.label}}</button></view><view class="card"><view class="row"><FIcon name="lock" :size="26"/><text class="h2">{{roleOptions.find(r=>r.value===accountRole)?.label}}权限</text></view><view class="notice small mt16">{{permissionNote}}</view><view v-for="p in permissions" :key="p.label" class="permission-row"><FIcon :name="p.enabled?'check':'lock'" :size="19"/><text class="grow" :class="{muted:!p.enabled}">{{p.label}}</text><text class="small" :class="p.enabled?'green':'muted'">{{p.enabled?'已开启':'未开启'}}</text></view></view><view class="section-head"><text class="h2">关联账号</text><button class="btn secondary small-btn" @tap="go('accountEdit')">＋ 新增账号</button></view><view v-for="a in state.accounts.filter(a=>a.role===accountRole)" :key="a.id" class="card row" @tap="go('accountEdit',{id:a.id})"><view class="avatar"><FIcon name="user"/></view><view class="grow"><text class="strong">{{a.name}}</text><text class="muted small block mt8">{{a.username}}</text></view><text class="badge" :class="a.active?'completed':'cancelled'">{{a.active?'使用中':'已停用'}}</text><FIcon name="chevron" :size="16"/></view>
 </template>
 <template v-else-if="screen==='accountEdit'">
  <view class="card"><text class="h2">账号资料</text><label class="field"><text>登录账号</text><input v-model="accountForm.username" placeholder="英文、数字或下划线，至少3位" aria-label="登录账号"/></label><label class="field"><text>显示名称</text><input v-model="accountForm.name" aria-label="显示名称"/></label><view class="field"><text>账号角色</text><FSelect v-model="accountForm.role" :options="roleOptions"/></view><view v-if="accountForm.role==='store'" class="field"><text>所属门店</text><FSelect v-model="accountForm.storeId" :options="storeOptions"/></view><view v-if="accountForm.role==='supplier'" class="field"><text>所属供应商</text><FSelect v-model="accountForm.supplierId" :options="supplierOptions"/></view><label class="field"><text>{{accountForm.id?'新密码（留空保持原密码）':'初始密码'}}</text><input v-model="accountForm.password" password placeholder="至少8位" aria-label="账号密码"/></label><view class="field horizontal"><text>账号状态</text><switch :checked="!!accountForm.active" color="#154D3D" @change="accountForm.active=$event.detail.value?1:0"/><text>{{accountForm.active?'启用':'停用'}}</text></view></view><view class="action-bar"><button class="btn secondary grow" @tap="back">取消</button><button class="btn grow" :disabled="busy" @tap="saveAccount">保存账号</button></view>
 </template>
 <template v-else-if="screen==='manage'">
  <view class="profile-head row"><view class="profile-avatar"><FIcon name="settings" :size="32"/></view><view><text class="large-title">平台管理</text><text class="small muted block mt8">{{state.user.name}} · 管理员</text></view></view><view class="card menu-list"><button v-for="m in managementMenus" :key="m.screen" @tap="go(m.screen)"><FIcon :name="m.icon"/><text class="grow">{{m.label}}</text><FIcon name="chevron" :size="16"/></button></view><button class="btn secondary full mt16" @tap="go('settings')">账号设置</button>
 </template>
 <template v-else-if="screen==='feedback'">
  <view v-for="f in state.feedback" :key="f.id" class="card"><view class="row between"><text class="strong">{{f.accountName}}</text><text class="small muted">{{String(f.created_at).slice(0,10)}}</text></view><text class="block mt16">{{f.content}}</text></view><view v-if="!state.feedback.length" class="empty">暂无反馈</view>
 </template>
</view></template>
<script setup>
import {ref,reactive,computed,inject,watch} from 'vue';import FIcon from './FIcon.vue';import FoodPhoto from './FoodPhoto.vue';import FSelect from './FSelect.vue';import OrderCard from './OrderCard.vue';import {state,go,back,today,key,money,mutate,confirm,upload,exportFile} from '../lib/food'
const props=defineProps({screen:String,itemId:String,filter:String});const {run,busy}=inject('app');const search=ref(''),category=ref('全部'),activeFilter=ref(''),categories=['全部','蔬菜','肉禽','粮油'];const categoryOptions=categories.slice(1).map(c=>({value:c,label:c}));const activeFilters=[{value:'',label:'全部商品'},{value:'1',label:'已上架'},{value:'0',label:'已下架'}],entityStates=[{value:'',label:'全部'},{value:'1',label:'启用中'},{value:'0',label:'已停用'}];
const sum=orders=>orders.filter(o=>o.status!=='cancelled').reduce((s,o)=>s+Number(o.total||0),0),sumPaid=orders=>orders.reduce((s,o)=>s+Number(o.paid||0),0),due=orders=>orders.filter(o=>o.status==='completed').reduce((s,o)=>s+Number(o.total)-Number(o.paid),0);const todayOrders=computed(()=>state.orders.filter(o=>String(o.created_at).startsWith(today())&&o.status!=='cancelled'));const metrics=computed(()=>[{label:'今日订单',value:todayOrders.value.length,filter:''},{label:'待接单',value:state.orders.filter(o=>o.status==='pending').length,filter:'pending'},{label:'配送中',value:state.orders.filter(o=>o.status==='delivering').length,filter:'delivering'}]);const chart=computed(()=>Array.from({length:7},(_,i)=>({date:today(i-6),count:state.orders.filter(o=>String(o.created_at).startsWith(today(i-6))).length}))),chartMax=computed(()=>Math.max(1,...chart.value.map(d=>d.count)));const shortcuts=[{screen:'products',label:'食材管理',icon:'box',note:'管理商品与价格'},{screen:'stores',label:'门店管理',icon:'store',note:'管理合作门店'},{screen:'suppliers',label:'供应商管理',icon:'user',note:'维护供应商资料'},{screen:'bindings',label:'配送关系',icon:'truck',note:'门店与供应商绑定'}];
const filteredProducts=computed(()=>state.products.filter(p=>(category.value==='全部'||p.category===category.value)&&p.name.includes(search.value)&&(activeFilter.value===''||String(p.active)===activeFilter.value)));const productForm=ref({name:'',category:'蔬菜',unit:'斤',spec:'新鲜散装',price:'',minimum:1,image:'0',description:'',active:1});let productInitialized=false;const productSource=computed(()=>state.products.find(p=>String(p.id)===props.itemId));watch(productSource,p=>{if(p&&props.screen==='productEdit'&&!productInitialized){productForm.value={...p};productInitialized=true}},{immediate:true});
const entities=computed(()=>props.screen==='stores'?state.stores:state.suppliers),filteredEntities=computed(()=>entities.value.filter(e=>(e.name.includes(search.value)||e.contact.includes(search.value))&&(activeFilter.value===''||String(e.active)===activeFilter.value)));const entityForm=ref({name:'',contact:'',phone:'',address:'',active:1});let entityInitialized=false;const entitySource=computed(()=>(props.filter==='stores'?state.stores:state.suppliers).find(e=>String(e.id)===props.itemId));watch(entitySource,e=>{if(e&&props.screen==='entityEdit'&&!entityInitialized){entityForm.value={...e};entityInitialized=true}},{immediate:true});
const bindings=reactive({});const storeOptions=computed(()=>[{value:0,label:'全部门店'},...state.stores.map(s=>({value:s.id,label:s.name}))]),supplierOptions=computed(()=>[{value:0,label:'选择供应商'},...state.suppliers.filter(s=>s.active).map(s=>({value:s.id,label:s.name}))]);
const storeFilter=ref(props.filter?.startsWith('store:')?Number(props.filter.split(':')[1]):0),supplierFilter=ref(props.filter?.startsWith('supplier:')?Number(props.filter.split(':')[1]):0),selectedDate=ref(''),status=ref(props.filter&&!props.filter.includes(':')?props.filter:'');const orderTabs=[{value:'',label:'全部'},{value:'pending',label:'待接单'},{value:'preparing',label:'待备货'},{value:'ready',label:'待配送'},{value:'delivering',label:'配送中'},{value:'delivered',label:'待收货'},{value:'completed',label:'已完成'},{value:'issue',label:'异常'}];const filteredOrders=computed(()=>state.orders.filter(o=>(!status.value||o.status===status.value)&&(!storeFilter.value||o.store_id===storeFilter.value)&&(!supplierFilter.value||o.supplier_id===supplierFilter.value)&&(!selectedDate.value||String(o.created_at).startsWith(selectedDate.value))&&(!search.value||o.storeName.includes(search.value)||o.order_no.includes(search.value)||o.items.some(i=>i.name.includes(search.value)))));
const dateFrom=ref(today().slice(0,8)+'01'),dateTo=ref(today()),group=ref('store');const periodOrders=computed(()=>state.orders.filter(o=>o.status!=='cancelled'&&String(o.created_at).slice(0,10)>=dateFrom.value&&String(o.created_at).slice(0,10)<=dateTo.value));const reportRows=computed(()=>(group.value==='store'?state.stores:state.suppliers).map(e=>({...e,orders:periodOrders.value.filter(o=>o[group.value+'_id']===e.id)})));
const filteredSettlements=computed(()=>state.settlements.filter(s=>!storeFilter.value||s.store_id===storeFilter.value));const settlementForm=ref({storeId:Number(props.itemId)||0,amount:'',date:today(),note:'',requestKey:key()});const settlementAvailable=computed(()=>due(state.orders.filter(o=>o.store_id===Number(settlementForm.value.storeId))));
const accountRole=ref('supplier'),roleOptions=[{value:'admin',label:'平台管理员'},{value:'store',label:'门店采购员'},{value:'supplier',label:'供应商'}];const permissionNote=computed(()=>({admin:'管理全部门店、供应商、商品和订单',store:'仅可查看所属门店订单与账单',supplier:'仅可查看负责门店订单'})[accountRole.value]);const permissions=computed(()=>accountRole.value==='supplier'?[{label:'查看负责门店订单',enabled:true},{label:'接单与备货',enabled:true},{label:'更新配送状态',enabled:true},{label:'查看配送汇总',enabled:true},{label:'商品定价',enabled:false},{label:'查看全部门店账单',enabled:false}]:accountRole.value==='store'?[{label:'选购食材与下单',enabled:true},{label:'确认收货',enabled:true},{label:'查看所属门店账单',enabled:true},{label:'商品定价',enabled:false},{label:'查看其他门店订单',enabled:false}]:[{label:'商品管理与定价',enabled:true},{label:'门店与供应商管理',enabled:true},{label:'全部订单与异常处理',enabled:true},{label:'线下结算记录',enabled:true},{label:'账号与数据权限',enabled:true}]);
const accountForm=ref({username:'',name:'',role:'store',storeId:0,supplierId:0,password:'',active:1});let accountInitialized=false;const accountSource=computed(()=>state.accounts.find(a=>String(a.id)===props.itemId));watch(accountSource,a=>{if(a&&props.screen==='accountEdit'&&!accountInitialized){accountForm.value={...a,password:''};accountInitialized=true}},{immediate:true});const managementMenus=[...shortcuts,{screen:'reports',label:'对账报表',icon:'chart'},{screen:'settlements',label:'线下结算记录',icon:'wallet'},{screen:'accounts',label:'账号与权限',icon:'lock'},{screen:'feedback',label:'门店反馈',icon:'help'}];
function toggleProduct(p){run(async()=>{if(await confirm((p.active?'下架':'上架')+p.name+'？'))await mutate('/products',{...p,active:p.active?0:1})})}function chooseImage(){run(async()=>{productForm.value.image=await upload()})}function saveProduct(){run(async()=>{await mutate('/products',productForm.value);go('products',{},true)})}function saveEntity(){run(async()=>{await mutate('/'+props.filter,entityForm.value);go(props.filter,{},true)})}function saveBinding(s){run(()=>mutate('/bindings',{storeId:s.id,supplierId:bindings[s.id]||s.supplier_id},'配送关系已更新'))}
function saveSettlement(){run(async()=>{if(!settlementForm.value.storeId)throw new Error('请选择门店');if(await confirm('登记这笔线下收款？','请确认款项已实际收到。记录保存后将分配至未结清订单。')){await mutate('/settlements',settlementForm.value,'结算记录已保存');settlementForm.value={storeId:settlementForm.value.storeId,amount:'',date:today(),note:'',requestKey:key()}}})}function saveAccount(){run(async()=>{const role=state.user.role;await mutate('/accounts',accountForm.value);go(state.user?'accounts':'login',{role},true)})}
function exportOrders(){run(()=>exportFile('orders',{from:selectedDate.value,to:selectedDate.value,storeId:storeFilter.value||'',supplierId:supplierFilter.value||'',status:status.value,search:search.value}))}function exportReports(){run(()=>exportFile('orders',{from:dateFrom.value,to:dateTo.value,excludeCancelled:'true'}))}function exportSettlements(){run(()=>exportFile('settlements',{storeId:storeFilter.value||''}))}
</script>

